<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Przestrzenie'; ?>
<div class="page-head"><div><p class="eyebrow">Wiki</p><h1>Przestrzenie</h1></div></div><div class="split"><section class="card"><h2>Dostępne przestrzenie</h2><?php if(!$spaces):?><p class="muted">Nie masz jeszcze dostępu do żadnej przestrzeni.</p><?php endif;?><?php foreach($spaces as $s):?><a class="space-card" href="<?=Html::e(Url::to('/spaces/'.$s['space_key']))?>"><strong><?=Html::e($s['name'])?></strong><span><?=Html::e($s['space_key'])?><?=in_array((int)$s['id'],$favoriteSpaceIds,true)?' · Ulubiona':''?></span><p><?=Html::e($s['description'])?></p></a><?php endforeach;?></section><?php if($canCreate):?><section class="card"><h2>Nowa przestrzeń</h2><form method="post" action="<?=Html::e(Url::to('/spaces'))?>"><?=Csrf::field()?><label>Nazwa<input name="name" required></label><label>Klucz<input name="key" maxlength="20" placeholder="IT" required></label><label>Opis<textarea name="description" rows="4"></textarea></label><button class="button">Utwórz przestrzeń</button></form></section><?php endif;?></div>
